function statusColor(status) {
  const good = ["Completed", "Confirmed", "Ready", "Active", "Available", "Paid Outside App"];
  const bad = ["Cancelled", "Past Due"];
  const warm = ["Technician En Route", "In Progress", "Processing", "Pending Billing", "Scheduled For Delivery", "Scheduled for Delivery"];
  if (good.includes(status)) return { color: "#2F5D34", bg: "#E4EFDE" };
  if (bad.includes(status)) return { color: "#8C2D2D", bg: "#F4E1DF" };
  if (warm.includes(status)) return { color: "#8A5A15", bg: "#F6E9CF" };
  return { color: C.steel, bg: "#E4EDF2" };
}

