function planStatusBadge(status) {
  const map = { active: "Active", past_due: "Past Due", cancelled: "Cancelled", trial: "Trial" };
  return map[status] || humanize(status);
}

// Maps a service-request category to the canonical "included_services" label
// used on membership plans, so we can tell a customer "this is already covered."
function mapCategoryToIncludedService(serviceLine, category) {
  if (serviceLine === "hvac" && ["Air Conditioner", "Furnace", "Heat Pump"].includes(category)) return "HVAC Maintenance";
  if (serviceLine === "plumbing" && category === "Water Heater") return "Water Heater Inspection";
  if (serviceLine === "electrical" && category === "Panel / Breaker") return "Electrical Inspection";
  if (serviceLine === "home_inspection") return "Home Inspection";
  if (serviceLine === "radon" && category === "Radon Test") return "Radon Test";
  return null;
}

// Annual visit allowance per included service, varying slightly by plan tier
// (e.g. Comfort and up include 2 HVAC visits/year instead of 1).
function visitAllowance(planName, service) {
  if (service === "HVAC Maintenance") return planName === "Essential" ? 1 : 2;
  return 1;
}

function MembershipPlanCard({ plan, cycle, isCurrent, onChoose, loading }) {
  const price = cycle === "annual" ? plan.annual_price : plan.monthly_price;
  const unit = cycle === "annual" ? "/year" : "/month";
  const equivalent = cycle === "monthly" ? `$${(plan.monthly_price * 12).toFixed(0)}/year if paid monthly` : `$${(plan.annual_price / 12).toFixed(0)}/month equivalent`;
  return (
    <Card style={{
      border: plan.is_highlighted ? `2px solid ${C.terracotta}` : `1px solid ${C.line}`,
      position: "relative", display: "flex", flexDirection: "column", gap: 10,
    }}>
      {plan.is_highlighted && (
        <div style={{ position: "absolute", top: -11, left: 16, background: C.terracotta, color: "#fff", fontFamily: BODY, fontWeight: 700, fontSize: 10.5, padding: "3px 10px", borderRadius: 999 }}>MOST POPULAR</div>
      )}
      <div style={{ fontFamily: DISPLAY, fontWeight: 700, fontSize: 18, marginTop: plan.is_highlighted ? 6 : 0 }}>{plan.name}</div>
      <div style={{ fontFamily: BODY, fontSize: 12.5, color: C.ash, marginTop: -6 }}>{plan.tagline}</div>
      <div>
        <span style={{ fontFamily: DISPLAY, fontWeight: 700, fontSize: 26, color: C.ink }}>${price}</span>
        <span style={{ fontFamily: BODY, fontSize: 13, color: C.ash }}>{unit}</span>
      </div>
      <div style={{ fontFamily: BODY, fontSize: 11.5, color: C.ash, marginTop: -8 }}>{equivalent}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 4 }}>
        {(plan.benefits || []).map((b) => (
          <div key={b} style={{ display: "flex", gap: 8, alignItems: "flex-start", fontFamily: BODY, fontSize: 13 }}>
            <CheckCircle2 size={15} color={C.leaf} style={{ marginTop: 1, flexShrink: 0 }} /> <span>{b}</span>
          </div>
        ))}
      </div>
      <div style={{ marginTop: 8 }}>
        {isCurrent ? (
          <GhostButton full>Current Plan</GhostButton>
        ) : (
          <PrimaryButton full disabled={loading} onClick={() => onChoose(plan)}>{loading ? "Please wait…" : "Choose Plan"}</PrimaryButton>
        )}
      </div>
    </Card>
  );
}

