function EditAddressScreen({ nav, property, onSave, loading, error }) {
  const [form, setForm] = useState({
    addressLine1: property?.address_line1 || "", city: property?.city || "",
    state: property?.state || "", postalCode: property?.postal_code || "",
  });
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const addressInputRef = useGooglePlacesAutocomplete(true, (parsed) => setForm((f) => ({ ...f, ...parsed })));
  const inputStyle = { fontFamily: BODY, padding: "13px 14px", borderRadius: 12, border: `1.5px solid ${C.line}`, fontSize: 15, background: C.paper, width: "100%" };

  const save = async () => {
    const ok = await onSave(form);
    if (ok) nav("account");
  };

  return (
    <div style={{ height: "100%", overflowY: "auto" }}>
      <AppBar title="Edit Service Address" onBack={() => nav("account")} />
      <div style={{ padding: "0 18px 30px", display: "flex", flexDirection: "column", gap: 10 }}>
        <div style={{ fontFamily: BODY, fontSize: 12.5, color: C.ash, marginBottom: 4 }}>
          Moving? Start typing your new address and pick it from the suggestions, or edit the fields directly.
        </div>
        <input ref={addressInputRef} autoComplete="off" style={inputStyle} placeholder="Street address" value={form.addressLine1} onChange={(e) => set("addressLine1", e.target.value)} />
        <input style={inputStyle} placeholder="City" value={form.city} onChange={(e) => set("city", e.target.value)} />
        <div style={{ display: "flex", gap: 10 }}>
          <input style={{ ...inputStyle, flex: 1 }} placeholder="State" value={form.state} onChange={(e) => set("state", e.target.value)} />
          <input style={{ ...inputStyle, flex: 1 }} placeholder="ZIP code" value={form.postalCode} onChange={(e) => set("postalCode", e.target.value)} />
        </div>
        {error && <div style={{ fontFamily: BODY, fontSize: 12.5, color: C.maple }}>{error}</div>}
        <div style={{ marginTop: 8 }}><PrimaryButton full disabled={loading} onClick={save}>{loading ? "Saving…" : "Save Address"}</PrimaryButton></div>
      </div>
    </div>
  );
}

/* ============================= CUSTOMER APP SHELL ============================= */

const TABS = [
  { key: "home", label: "Home", icon: Home },
  { key: "service", label: "Service", icon: Wrench },
  { key: "orders", label: "Orders", icon: Package },
  { key: "equipment", label: "Equipment", icon: Boxes },
  { key: "account", label: "Account", icon: User },
];

function toISODate(d) {
  return d.toISOString().slice(0, 10);
}

function CustomerApp() {
  const [session, setSession] = useState(null); // { access_token, user }
  const [authLoading, setAuthLoading] = useState(false);
  const [authError, setAuthError] = useState(null);
  const [authInfo, setAuthInfo] = useState(null);

  const [dataLoading, setDataLoading] = useState(false);
  const [data, setData] = useState(null); // everything fetched after login
  const [screen, setScreen] = useState("home");
  const [navPayload, setNavPayload] = useState(null);
  const [lastReq, setLastReq] = useState(null);
  const [lastOrder, setLastOrder] = useState(null);
  const [planActionLoading, setPlanActionLoading] = useState(false);
  const [planActionError, setPlanActionError] = useState(null);
  const [addressActionLoading, setAddressActionLoading] = useState(false);
  const [addressActionError, setAddressActionError] = useState(null);

  const nav = (s, payload) => { setScreen(s); setNavPayload(payload || null); };

  const fetchAll = async (token, userId) => {
    setDataLoading(true);
    try {
      const customerRows = await restRequest(`customers?select=*&user_id=eq.${userId}`, { token });
      const customer = customerRows[0];
      const properties = await restRequest(`properties?select=*&customer_id=eq.${customer.id}&order=is_primary.desc&limit=1`, { token });
      const property = properties[0];
      const [equipment, serviceLines, products, requests, appointments, orders, reminders, notifications, plans, memberships, serviceRecords, settingsRows, promos, notifPrefs] = await Promise.all([
        property ? restRequest(`equipment?select=*&property_id=eq.${property.id}`, { token }) : Promise.resolve([]),
        restRequest(`service_lines?select=*&order=sort_order.asc`, { token }),
        restRequest(`products?select=*,product_categories(name)&is_active=eq.true&order=name.asc`, { token }),
        restRequest(`service_requests?select=*&customer_id=eq.${customer.id}&order=created_at.desc`, { token }),
        restRequest(`appointments?select=*&customer_id=eq.${customer.id}&order=scheduled_date.asc.nullslast`, { token }),
        restRequest(`orders?select=*,order_items(quantity,unit_price_at_order,products(name))&customer_id=eq.${customer.id}&order=created_at.desc`, { token }),
        restRequest(`reminders?select=*&customer_id=eq.${customer.id}&order=due_date.asc`, { token }),
        restRequest(`notifications?select=*&customer_id=eq.${customer.id}&order=created_at.desc`, { token }),
        restRequest(`maintenance_plans?select=*&is_active=eq.true&order=sort_order.asc`, { token }),
        restRequest(`customer_memberships?select=*&customer_id=eq.${customer.id}&order=created_at.desc&limit=1`, { token }),
        restRequest(`service_records?select=*,technicians(first_name,last_name)&customer_id=eq.${customer.id}&order=service_date.desc`, { token }),
        restRequest(`business_settings?select=*`, { token }),
        restRequest(`promotions?select=*&is_active=eq.true&order=start_date.desc`, { token }),
        restRequest(`notification_preferences?select=*&customer_id=eq.${customer.id}`, { token }),
      ]);
      const settings = Object.fromEntries(settingsRows.map((s) => [s.key, s.value]));
      const membership = memberships[0] || null;
      const plan = membership ? plans.find((p) => p.id === membership.maintenance_plan_id) : null;
      setData({
        customer, property, equipment, serviceLines, products, requests, appointments, orders,
        reminders, notifications, plans, membership, plan, serviceRecords, settings, promotions: promos,
        emergencyEnabled: settings.emergency_service_enabled === true || settings.emergency_service_enabled === "true",
        marketingEnabled: notifPrefs[0] ? notifPrefs[0].marketing_enabled : true,
      });
    } catch (e) {
      setAuthError(e.message);
    } finally {
      setDataLoading(false);
    }
  };

  const handleSignIn = async (form) => {
    setAuthLoading(true); setAuthError(null); setAuthInfo(null);
    try {
      const res = await signInRequest({ email: form.email, password: form.password });
      setSession({ access_token: res.access_token, user: res.user });
      await fetchAll(res.access_token, res.user.id);
    } catch (e) {
      setAuthError(e.message);
    } finally {
      setAuthLoading(false);
    }
  };

  const handleSignUp = async (form) => {
    setAuthLoading(true); setAuthError(null); setAuthInfo(null);
    try {
      const res = await signUpRequest(form);
      if (res.access_token) {
        setSession({ access_token: res.access_token, user: res.user });
        await fetchAll(res.access_token, res.user.id);
      } else {
        setAuthInfo("Account created — check your email to confirm, then log in below.");
      }
    } catch (e) {
      setAuthError(e.message);
    } finally {
      setAuthLoading(false);
    }
  };

  const logOut = () => { setSession(null); setData(null); setScreen("home"); };

  const submitRequest = async (form) => {
    const line = data.serviceLines.find((l) => l.key === form.serviceLine);
    const includedService = mapCategoryToIncludedService(form.serviceLine, form.category);
    const covered = data.plan && includedService && (data.plan.included_services || []).includes(includedService);
    const payload = [{
      request_number: "SR-" + Math.floor(50000 + Math.random() * 9000),
      customer_id: data.customer.id,
      property_id: data.property.id,
      service_line_id: line.id,
      category: form.category,
      problem_description: form.problem || "No description provided",
      urgency: toEnum(form.urgency),
      preferred_date: form.date || null,
      preferred_window: form.window || null,
      status: "submitted",
      internal_notes: covered ? `Covered by ${data.plan.name} membership` : null,
    }];
    const inserted = await restRequest("service_requests", { method: "POST", token: session.access_token, body: payload, prefer: "return=representation" });
    setData((d) => ({ ...d, requests: [inserted[0], ...d.requests] }));
    setLastReq(inserted[0]);
    setScreen("requestConfirmed");
  };

  const submitAppt = async (form) => {
    const payload = [{
      appointment_number: "AP-" + Math.floor(3000 + Math.random() * 900),
      customer_id: data.customer.id,
      property_id: data.property.id,
      appointment_type: form.type,
      scheduled_date: form.date || null,
      scheduled_window: form.window || null,
      status: "requested",
      customer_notes: form.notes || null,
    }];
    const inserted = await restRequest("appointments", { method: "POST", token: session.access_token, body: payload, prefer: "return=representation" });
    setData((d) => ({ ...d, appointments: [...d.appointments, inserted[0]] }));
    setScreen("appointments");
  };

  const placeOrder = async (items, delivery, notes, deliveryFee) => {
    const orderPayload = [{
      order_number: "LCS-" + Math.floor(1000 + Math.random() * 9000),
      customer_id: data.customer.id,
      property_id: data.property.id,
      status: "submitted",
      billing_status: "not_billed",
      delivery_preference: delivery,
      customer_notes: notes || null,
      internal_notes: deliveryFee > 0 ? `Delivery fee: $${deliveryFee.toFixed(2)}` : (delivery === "delivery" ? "Delivery fee waived (3+ filters)" : null),
    }];
    const [order] = await restRequest("orders", { method: "POST", token: session.access_token, body: orderPayload, prefer: "return=representation" });
    const itemsPayload = items.map((it) => ({ order_id: order.id, product_id: it.product_id, quantity: it.quantity, unit_price_at_order: it.unit_price }));
    await restRequest("order_items", { method: "POST", token: session.access_token, body: itemsPayload });
    const fullOrder = { ...order, order_items: items.map((it) => ({ quantity: it.quantity, products: { name: it.name } })) };
    setData((d) => ({ ...d, orders: [fullOrder, ...d.orders] }));
    setLastOrder(order);
    setScreen("orderConfirmed");
  };

  const dismissReminder = async (id) => {
    await restRequest(`reminders?id=eq.${id}`, { method: "PATCH", token: session.access_token, body: { status: "snoozed" } });
    setData((d) => ({ ...d, reminders: d.reminders.map((r) => (r.id === id ? { ...r, status: "snoozed" } : r)) }));
  };
  const completeReminder = async (id) => {
    await restRequest(`reminders?id=eq.${id}`, { method: "PATCH", token: session.access_token, body: { status: "completed" } });
    setData((d) => ({ ...d, reminders: d.reminders.map((r) => (r.id === id ? { ...r, status: "completed" } : r)) }));
  };

  const chooseMembershipPlan = async (plan, cycle) => {
    setPlanActionLoading(true); setPlanActionError(null);
    try {
      const today = new Date();
      const renewal = new Date(today);
      if (cycle === "annual") renewal.setFullYear(renewal.getFullYear() + 1); else renewal.setMonth(renewal.getMonth() + 1);
      const body = {
        customer_id: data.customer.id, maintenance_plan_id: plan.id, status: "active",
        start_date: toISODate(today), renewal_date: toISODate(renewal), billing_cycle: cycle,
      };
      let membership;
      if (data.membership) {
        [membership] = await restRequest(`customer_memberships?id=eq.${data.membership.id}`, { method: "PATCH", token: session.access_token, body, prefer: "return=representation" });
      } else {
        [membership] = await restRequest("customer_memberships", { method: "POST", token: session.access_token, body: [body], prefer: "return=representation" });
      }
      setData((d) => ({ ...d, membership, plan }));
      setScreen("plan");
    } catch (e) {
      setPlanActionError(e.message);
    } finally {
      setPlanActionLoading(false);
    }
  };

  const cancelMembership = async () => {
    setPlanActionLoading(true);
    try {
      const [membership] = await restRequest(`customer_memberships?id=eq.${data.membership.id}`, { method: "PATCH", token: session.access_token, body: { status: "cancelled" }, prefer: "return=representation" });
      setData((d) => ({ ...d, membership }));
    } finally {
      setPlanActionLoading(false);
    }
  };

  const toggleMarketing = async () => {
    const next = !data.marketingEnabled;
    setData((d) => ({ ...d, marketingEnabled: next }));
    await restRequest(`notification_preferences?customer_id=eq.${data.customer.id}`, { method: "PATCH", token: session.access_token, body: { marketing_enabled: next } });
  };

  const updateAddress = async (form) => {
    setAddressActionLoading(true); setAddressActionError(null);
    try {
      const body = { address_line1: form.addressLine1, city: form.city, state: form.state, postal_code: form.postalCode };
      const [property] = await restRequest(`properties?id=eq.${data.property.id}`, { method: "PATCH", token: session.access_token, body, prefer: "return=representation" });
      setData((d) => ({ ...d, property }));
      return true;
    } catch (e) {
      setAddressActionError(e.message);
      return false;
    } finally {
      setAddressActionLoading(false);
    }
  };

  if (!session) return <LoginScreen onSignIn={handleSignIn} onSignUp={handleSignUp} loading={authLoading} error={authError} info={authInfo} />;
  if (dataLoading || !data) {
    return (
      <div style={{ height: "100%", display: "flex", alignItems: "center", justifyContent: "center", background: C.cream }}>
        <div style={{ fontFamily: BODY, color: C.ash }}>{authError || "Loading your account…"}</div>
      </div>
    );
  }

  let body;
  if (screen === "home") body = <CustomerHome nav={nav} state={data} />;
  else if (screen === "service" || screen === "newRequest") body = <NewRequestScreen nav={nav} submit={submitRequest} serviceLines={data.serviceLines} membershipInfo={{ plan: data.plan }} />;
  else if (screen === "requestConfirmed") body = <RequestConfirmed req={lastReq} nav={nav} />;
  else if (screen === "emergency") body = <EmergencyScreen nav={nav} emergencyEnabled={data.emergencyEnabled} />;
  else if (screen === "scheduleAppt") body = <ScheduleApptScreen nav={nav} submit={submitAppt} navPayload={navPayload} serviceLines={data.serviceLines} />;
  else if (screen === "appointments") body = <AppointmentsScreen nav={nav} appointments={data.appointments} />;
  else if (screen === "orderFilters") body = <OrderFiltersScreen nav={nav} placeOrder={placeOrder} products={data.products} />;
  else if (screen === "orderConfirmed") body = <OrderConfirmed order={lastOrder} nav={nav} />;
  else if (screen === "orders") body = <OrdersScreen nav={nav} orders={data.orders} />;
  else if (screen === "equipment") body = <EquipmentScreen nav={nav} equipment={data.equipment} />;
  else if (screen === "history") body = <HistoryScreen nav={nav} serviceRecords={data.serviceRecords} />;
  else if (screen === "plan") body = <MembershipDashboardScreen nav={nav} membership={data.membership} plan={data.plan} serviceRecords={data.serviceRecords} onCancel={cancelMembership} cancelLoading={planActionLoading} />;
  else if (screen === "membershipPlans") body = <MembershipPlansScreen nav={nav} plans={data.plans} membership={data.membership} onChoose={chooseMembershipPlan} loading={planActionLoading} error={planActionError} />;
  else if (screen === "reminders") body = <RemindersScreen nav={nav} reminders={data.reminders} onOrder={() => nav("orderFilters")} onDismiss={dismissReminder} onComplete={completeReminder} />;
  else if (screen === "promotions") body = <PromotionsScreen nav={nav} promotions={data.promotions} />;
  else if (screen === "financing") body = <FinancingScreen nav={nav} />;
  else if (screen === "rebates") body = <RebatesScreen nav={nav} />;
  else if (screen === "contact") body = <ContactScreen nav={nav} />;
  else if (screen === "notifications") body = <NotificationsScreen nav={nav} notifications={data.notifications} marketingEnabled={data.marketingEnabled} onToggleMarketing={toggleMarketing} />;
  else if (screen === "account") body = <AccountScreen nav={nav} customer={data.customer} property={data.property} onLogOut={logOut} />;
  else if (screen === "editAddress") body = <EditAddressScreen nav={nav} property={data.property} onSave={updateAddress} loading={addressActionLoading} error={addressActionError} />;
  else body = <CustomerHome nav={nav} state={data} />;

  const tabKey = ["newRequest", "requestConfirmed", "emergency", "scheduleAppt"].includes(screen) ? "service"
    : ["orderFilters", "orderConfirmed"].includes(screen) ? "orders"
    : ["history", "plan", "membershipPlans", "reminders", "promotions", "financing", "rebates", "contact", "notifications", "editAddress"].includes(screen) ? "account"
    : screen === "appointments" ? "home"
    : screen;

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", background: C.cream }}>
      <div style={{ flex: 1, overflow: "hidden" }}>{body}</div>
      <div style={{ display: "flex", borderTop: `1px solid ${C.line}`, background: "#fff" }}>
        {TABS.map(t => (
          <div key={t.key} onClick={() => nav(t.key)} style={{ flex: 1, textAlign: "center", padding: "10px 0 12px", cursor: "pointer" }}>
            <t.icon size={20} color={tabKey === t.key ? C.terracotta : C.ash} style={{ margin: "0 auto" }} />
            <div style={{ fontFamily: BODY, fontSize: 10.5, fontWeight: 600, color: tabKey === t.key ? C.terracotta : C.ash, marginTop: 3 }}>{t.label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

